body{margin:0;font-family:"Open Sans","Inter","Segoe UI",Arial,sans-serif;color:#e2e8f0;background:#1e293b;}
.wrap{display:flex;flex-direction:column;height:100%;background:#1e293b;}
.meta{padding:10px 24px 0;color:#94a3b8;font-size:13px;text-align:right;}
.scroll{overflow:auto;flex:1;}
.tbl{width:100%;border-collapse:collapse;font-size:14px;}
.tbl th{text-align:left;padding:14px 18px;color:#cbd5e1;font-weight:700;font-size:14px;background:#0f172a;border-bottom:1px solid #334155;cursor:pointer;user-select:none;white-space:nowrap;position:sticky;top:0;z-index:1;}
.tbl th.noSort{cursor:default;}
.tbl th .sort{display:inline-flex;flex-direction:column;margin-left:6px;line-height:0.7;vertical-align:middle;}
.tbl th .sort span{font-size:10px;color:#64748b;}
.tbl th .sort span.active{color:#ffffff;}
.tbl td{padding:13px 18px;border:0;color:#e2e8f0;vertical-align:top;white-space:nowrap;}
.tbl td>div{white-space:normal;word-break:break-word;}
.tbl tbody tr:nth-child(odd) td{background:#1e293b;}
.tbl tbody tr:nth-child(even) td{background:#0f172a;}
.tbl tbody tr:hover td{background:#26344b;}
.badge{display:inline-block;padding:2px 10px;border-radius:12px;font-size:12px;font-weight:600;}
.b-error{background:#4c1d1d;color:#f87171;}
.b-warning{background:#422f0b;color:#fbbf24;}
.b-info{background:#173049;color:#60a5fa;}
.b-default{background:#334155;color:#cbd5e1;}
.maplink{color:#60a5fa;text-decoration:none;cursor:pointer;font-weight:500;}
.maplink:hover{text-decoration:underline;}
.empty{padding:30px;text-align:center;color:#64748b;font-style:italic;}
.pager{display:flex;align-items:center;gap:8px;padding:14px 24px;border-top:1px solid #334155;background:#0f172a;}
.pbtn{background:transparent;border:none;color:#cbd5e1;cursor:pointer;padding:6px 8px;border-radius:4px;font-size:16px;}
.pbtn:disabled{color:#475569;cursor:not-allowed;}
.pbtn:hover:not(:disabled){background:#1e293b;}
.pnum{min-width:30px;text-align:center;background:#1E293B;color:#ffffff;border-radius:4px;padding:4px 10px;font-weight:600;border:1px solid #334155;}
.gotolbl{color:#cbd5e1;font-size:14px;}
.goto{width:60px;padding:6px 8px;border:1px solid #334155;border-radius:4px;font-size:14px;outline:none;background:#1e293b;color:#ffffff;}
.goto:focus{border-color:#64748b;}
.psize{margin-left:auto;background:#1e293b;color:#ffffff;border:1px solid #334155;border-radius:4px;padding:6px 10px;font-size:14px;outline:none;cursor:pointer;}
.psize:focus{border-color:#64748b;}
.skel{padding:18px 24px;color:#94a3b8;}

.tiles{display:flex;gap:14px;padding:14px 20px;flex-wrap:wrap;}
.tile{flex:1 1 150px;min-width:150px;background:#0f172a;border:1px solid #334155;border-radius:8px;padding:12px 14px;}
.tile .lbl{color:#94a3b8;font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.04em;}
.tile .big{color:#f1f5f9;font-size:26px;font-weight:700;margin-top:6px;line-height:1.1;}
.tile .sub{color:#64748b;font-size:12px;margin-top:4px;}
.tile .blocked{color:#f87171;font-size:12px;margin-top:6px;font-weight:600;}
.tile .ok{color:#4ade80;font-size:12px;margin-top:6px;font-weight:600;}

