import React, { useState, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

const n = (v) => (Number(v) || 0).toLocaleString();

function App() {
  const [model, setModel] = useState(appsmith.model || {});
  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  if (model.isLoading) return React.createElement("div", { className: "skel" }, "Loading stage totals...");
  const rows = (model && model.data) || [];
  if (!rows.length) return React.createElement("div", { className: "skel" }, "No validation errors in this window.");

  // An all-stage tile first, so the page leads with the size of the problem.
  const sum = (k) => rows.reduce((a, r) => a + (Number(r[k]) || 0), 0);
  const allOpen = sum("Open"), allTotal = sum("Total"), allBlocked = sum("Open, Not Resolvable");

  const tile = (label, open, total, blocked, pct) =>
    React.createElement("div", { className: "tile", key: label },
      React.createElement("div", { className: "lbl" }, label),
      React.createElement("div", { className: "big" }, n(open)),
      React.createElement("div", { className: "sub" }, "open of " + n(total) +
        (pct == null ? "" : "  ·  " + pct + "% resolved")),
      blocked > 0
        ? React.createElement("div", { className: "blocked" }, n(blocked) + " not resolvable")
        : React.createElement("div", { className: "ok" }, "all resolvable"));

  return React.createElement("div", { className: "wrap" },
    React.createElement("div", { className: "tiles" },
      [tile("All Stages", allOpen, allTotal, allBlocked,
            allTotal ? Math.round(1000 * (allTotal - allOpen) / allTotal) / 10 : null)]
        .concat(rows.map((r) =>
          tile(r["Stage"], r["Open"], r["Total"], r["Open, Not Resolvable"], r["Resolved %"])))));
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

